String buildAndroidMapsChannel(String packageName) =>
    '''package $packageName

import android.app.Activity
import android.content.ActivityNotFoundException
import android.content.Intent
import android.net.Uri
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.embedding.engine.plugins.FlutterPlugin
import io.flutter.embedding.engine.plugins.activity.ActivityAware
import io.flutter.embedding.engine.plugins.activity.ActivityPluginBinding
import io.flutter.plugin.common.MethodCall
import io.flutter.plugin.common.MethodChannel

// Generated by mini_program_tooling. Do not edit.
internal class MiniProgramMapsChannel : FlutterPlugin, ActivityAware {
    companion object {
        fun register(engine: FlutterEngine) {
            if (!engine.plugins.has(MiniProgramMapsChannel::class.java)) {
                engine.plugins.add(MiniProgramMapsChannel())
            }
        }
    }
    private var activity: Activity? = null
    private var channel: MethodChannel? = null
    override fun onAttachedToEngine(binding: FlutterPlugin.FlutterPluginBinding) {
        channel = MethodChannel(binding.binaryMessenger, "mini_program/maps").also {
            it.setMethodCallHandler(::handleCall)
        }
    }
    override fun onDetachedFromEngine(binding: FlutterPlugin.FlutterPluginBinding) {
        channel?.setMethodCallHandler(null)
        channel = null
        activity = null
    }
    override fun onAttachedToActivity(binding: ActivityPluginBinding) { activity = binding.activity }
    override fun onReattachedToActivityForConfigChanges(binding: ActivityPluginBinding) { activity = binding.activity }
    override fun onDetachedFromActivityForConfigChanges() { activity = null }
    override fun onDetachedFromActivity() { activity = null }

$_body
}
''';

const _body = r'''
    private fun handleCall(call: MethodCall, result: MethodChannel.Result) {
        if (call.method != "openLocation" && call.method != "openDirections") {
            result.notImplemented(); return
        }
        val current = activity
        if (current == null || current.isFinishing || current.isDestroyed || !current.hasWindowFocus()) {
            result.error("maps_foreground_required", "An active foreground activity is required.", null); return
        }
        try {
            val args = call.arguments as? Map<*, *> ?: emptyMap<Any, Any>()
            val appId = args["miniProgramId"] as? String
            val lat = (args["latitude"] as? Number)?.toDouble()
            val lon = (args["longitude"] as? Number)?.toDouble()
            val name = args["name"] as? String
            val address = args["address"] as? String
            val system = args["coordinateSystem"] as? String
            val apps = args["preferredApps"] as? List<*>
            val directions = call.method == "openDirections"
            val mode = args["mode"] as? String
            if (appId.isNullOrBlank() || appId.length > 256 ||
                lat == null || !lat.isFinite() || lat !in -90.0..90.0 ||
                lon == null || !lon.isFinite() || lon !in -180.0..180.0 ||
                !validText(name, 120, false) || !validText(address, 512, true) ||
                system !in listOf("wgs84", "gcj02", "bd09") ||
                apps.isNullOrEmpty() || apps.size > 3 || apps.distinct().size != apps.size ||
                apps.any { it !in listOf("googleMaps", "amap", "baiduMaps") } ||
                (directions && mode !in listOf("driving", "walking"))) {
                result.error("maps_invalid_request", "Invalid map destination or host configuration.", null); return
            }
            var compatible = false
            for (app in apps) {
                if ((app == "googleMaps" && system != "wgs84") ||
                    (app == "amap" && system == "bd09")) continue
                compatible = true
                val uri = buildUri(app as String, directions, lat, lon, name!!.trim(), address!!.trim(), system!!, mode, current.packageName)
                val pkg = when (app) {
                    "googleMaps" -> "com.google.android.apps.maps"
                    "amap" -> "com.autonavi.minimap"
                    else -> "com.baidu.BaiduMap"
                }
                try {
                    // No NEW_TASK, CLEAR_TASK, or caller finish: Back can resume
                    // the existing embedded or separate-task mini-program.
                    current.startActivity(Intent(Intent.ACTION_VIEW, uri).setPackage(pkg))
                    result.success(null); return
                } catch (_: ActivityNotFoundException) {
                    // Try the next host-allowed, coordinate-compatible app.
                } catch (_: SecurityException) {
                    // Disabled/restricted handlers are treated as unavailable.
                }
            }
            if (!compatible) result.error("maps_coordinate_system_unsupported", "No configured map app supports these coordinates.", null)
            else result.error("maps_unavailable", "No compatible supported map app is available.", null)
        } catch (_: Exception) {
            result.error("maps_operation_failed", "The map application could not be opened.", null)
        }
    }

    private fun validText(value: String?, maximum: Int, empty: Boolean): Boolean =
        value != null && value.length <= maximum && (empty || value.isNotBlank()) &&
            value.none { it.code in 0..31 || it.code in 127..159 }

    private fun buildUri(app: String, directions: Boolean, lat: Double, lon: Double,
        name: String, address: String, system: String, mode: String?, hostPackage: String): Uri {
        val point = "$lat,$lon"
        return when (app) {
            "googleMaps" -> if (directions) {
                Uri.parse("https://www.google.com/maps/dir/").buildUpon()
                    .appendQueryParameter("api", "1")
                    .appendQueryParameter("destination", point)
                    .appendQueryParameter("travelmode", mode).build()
            } else {
                // Parentheses delimit a geo label; they cannot introduce a
                // second label or coordinate inside the provider's grammar.
                val label = name.replace('(', ' ').replace(')', ' ')
                Uri.parse("geo:0,0?q=" + Uri.encode("$point($label)"))
            }
            "amap" -> {
                val builder = Uri.parse(if (directions) "amapuri://route/plan/" else "androidamap://viewMap").buildUpon()
                    .appendQueryParameter("sourceApplication", hostPackage)
                    .appendQueryParameter("dev", if (system == "wgs84") "1" else "0")
                if (directions) builder.appendQueryParameter("dlat", lat.toString())
                    .appendQueryParameter("dlon", lon.toString())
                    .appendQueryParameter("dname", name)
                    .appendQueryParameter("t", if (mode == "walking") "2" else "0")
                else builder.appendQueryParameter("lat", lat.toString())
                    .appendQueryParameter("lon", lon.toString()).appendQueryParameter("poiname", name)
                builder.build()
            }
            else -> {
                val builder = Uri.parse(if (directions) "baidumap://map/direction" else "baidumap://map/marker").buildUpon()
                    .appendQueryParameter("src", "andr.$hostPackage")
                    .appendQueryParameter("coord_type", if (system == "bd09") "bd09ll" else system)
                if (directions) builder.appendQueryParameter("origin", "我的位置")
                    // Coordinates alone avoid name/latlng nested syntax injection.
                    .appendQueryParameter("destination", point).appendQueryParameter("mode", mode)
                else builder.appendQueryParameter("location", point)
                    .appendQueryParameter("title", name).appendQueryParameter("content", address)
                builder.build()
            }
        }
    }
''';
